#!/usr/bin/env node
// SPDX-License-Identifier: AGPL-3.0-only
/**
 * Writes src/lang/en.facts.generated.mjs: the shards of handover/lang.en that the thin local module src/lang/en.mjs reads (the English grammar as facts), as one browser-safe module of texts.
 * Until the knowledge repository publishes `w.lang.en` (and the library `std.grammar` reads it), handover/lang.en is the source of truth; edit the .sop shards, then run this. tests/lang-en.test.mjs fails when the
 * generated file is stale.
 *
 *   node scripts/build-lang-en.mjs [--check]
 */
import { readFileSync, writeFileSync } from 'node:fs';
import { resolve, dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';

const REPO = resolve(dirname(fileURLToPath(import.meta.url)), '..');
export const SHARDS = ['determiners', 'pronouns', 'prepositions', 'numbers', 'morphology', 'ellipsis', 'np'];
const strip = (t) => t.split('\n').filter((l) => !l.startsWith('#') && l.trim()).join('\n') + '\n';   // comments stay in handover; the module needs the wires

export function render() {
  const texts = Object.fromEntries(SHARDS.map((s) => [s, strip(readFileSync(join(REPO, 'handover/lang.en/shards', `${s}.sop`), 'utf8'))]));
  return `// GENERATED by scripts/build-lang-en.mjs from handover/lang.en/shards/{${SHARDS.join(',')}}.sop. Never edited by hand.\n// SPDX-License-Identifier: AGPL-3.0-only\nexport const LANG_EN_FACTS = ${JSON.stringify(texts, null, 1)};\n`;
}

if (process.argv[1] && resolve(process.argv[1]) === fileURLToPath(import.meta.url)) {
  const out = join(REPO, 'src/lang/en.facts.generated.mjs');
  const text = render();
  if (process.argv.includes('--check')) {
    let cur = ''; try { cur = readFileSync(out, 'utf8'); } catch { /* missing */ }
    if (cur !== text) { console.error('src/lang/en.facts.generated.mjs is stale: run node scripts/build-lang-en.mjs'); process.exit(1); }
  } else writeFileSync(out, text);
}
